		closeBtn.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		closeBtn.setForeground(Color.WHITE);
		closeBtn.setFont(FontManager.getRunescapeSmallFont());
		closeBtn.addActionListener(e ->
		{
